(() => {
  const button=document.querySelector('#readBtn'),result=document.querySelector('#resultCard'),host=document.querySelector('#interactiveResult');
  if(!button||!result||!host)return;
  const gods=[
    {name:'大安',meaning:'吉。身不動時，主穩定、平安、按部就班；事情可成，但不宜急推。',action:'先守住基本盤，按原定計劃完成第一步。',tone:'木／青龍／穩'},
    {name:'留連',meaning:'平或稍凶。人未歸，事情容易拖延、反覆、牽掛；資訊或對方未完全到位。',action:'不要逼自己即時定案，先查清楚阻力及等待條件。',tone:'拖／待'},
    {name:'速喜',meaning:'吉。人即至，喜事來；消息快、進展快，容易出現正面回應。',action:'有機會就即時跟進，但仍要核對條款及細節。',tone:'火／朱雀／快'},
    {name:'赤口',meaning:'凶。官非爭訟，口舌多；誤會及衝突會放大，溝通方式比內容更重要。',action:'避免衝動回覆，重要事情改用書面及留紀錄。',tone:'金／白虎／慎'},
    {name:'小吉',meaning:'吉。行人至，甚吉利；有小幅順利及幫助，但未到大成，適合試行。',action:'先做小規模測試，收集回饋後再加碼。',tone:'水／玄武／試'},
    {name:'空亡',meaning:'凶。音信稀，事不全；結果未定或暫時落空，現階段不宜過度解讀。',action:'補資料、驗證承諾，暫緩不可逆嘅決定。',tone:'空／未定'}
  ];
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const calc=()=>{const raw=document.querySelector('#momentTime')?.value||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()).replace(',','T'),d=new Date(`${raw}+08:00`),shichen=Math.floor((d.getHours()+1)/2)%12+1;let month=d.getMonth()+1,day=d.getDate();try{if(window.Solar){const lunar=Solar.fromYmdHms(d.getFullYear(),d.getMonth()+1,d.getDate(),d.getHours(),d.getMinutes(),0).getLunar();month=Math.abs(lunar.getMonth());day=lunar.getDay();}}catch(e){}let m=(month-1)%6,dayPos=(m+day-1)%6,timePos=(dayPos+shichen-1)%6;return {raw,month,day,shichen,m,dayPos,timePos,god:gods[timePos]};};
  const render=()=>{if(document.querySelector('.method.active')?.dataset.name!=='小六壬')return;const q=document.querySelector('#question')?.value.trim()||'目前最重要的選擇',x=calc(),g=x.god;document.querySelector('#resultTitle').textContent='小六壬 · 六神解讀';document.querySelector('#resultText').textContent=`問題：「${q}」\n\n起卦時間：${x.raw}\n起法：大安起正月 → 月上起日 → 日上起時\n農曆月 ${x.month} → 農曆日 ${x.day} → 時辰 ${x.shichen}\n結果：${g.name}\n\n${g.meaning}\n\n針對問題「${q}」：${g.action}\n\n小六壬只作當下趨勢提示；如果涉及工作、金錢或關係，仍要用現實資料覆核。`;host.hidden=false;result.classList.add('visual-mode');host.innerHTML=`<div class="chart-intro"><span>互動小六壬 · 掐指一算</span><strong>落宮：「${g.name}」</strong></div><div class="liuren-method-note"><b>點樣計？</b><span>左手六個固定關節位依次為：大安 → 留連 → 速喜 → 赤口 → 小吉 → 空亡。</span><span>大安起正月，再由月上起日，最後由日上起時；最後落點用來讀當下事情節奏。</span></div><div class="liuren-steps"><div><small>01</small><b>月上起月</b><span>農曆 ${x.month} 月</span></div><div><small>02</small><b>月上起日</b><span>農曆 ${x.day} 日</span></div><div><small>03</small><b>日上起時</b><span>第 ${x.shichen} 個時辰</span></div></div><div class="liuren-board">${gods.map((item,i)=>`<button class="liuren-card ${i===x.timePos?'is-selected':''}" data-index="${i}"><small>${i+1}</small><strong>${item.name}</strong><span>${item.tone}</span></button>`).join('')}</div><div class="liuren-detail"><p class="eyebrow">CURRENT SIGN</p><h4>${g.name}</h4><p>${g.meaning}</p><p><b>針對你嘅問題：</b>${g.action}</p></div>`;host.querySelectorAll('.liuren-card').forEach((card,i)=>card.onclick=()=>{const item=gods[i];host.querySelector('.liuren-detail').innerHTML=`<p class="eyebrow">SIX SPIRITS · ${i+1}/6</p><h4>${item.name}</h4><p>${item.meaning}</p><p><b>實際做法：</b>${item.action}</p>`;host.querySelectorAll('.liuren-card').forEach((c,n)=>c.classList.toggle('is-selected',n===i));});};
  button.addEventListener('click',()=>setTimeout(render,120));
})();
